  /** Create the runnable */
  const runnableAgent = RunnableSequence.from([
    {
      input: (i: { input: string; steps: Array<AgentStep> }) => i.input,
      agent_scratchpad: (i: { input: string; steps: Array<AgentStep> }) =>
        formatForOpenAIFunctions(i.steps),
