  }): Promise<void> {
    const { ids, filter } = params;

    if (ids && ids.length > 0) {
      for (const id of ids) {
        let deleter = this.client.data
          .deleter()
          .withClassName(this.indexName)
          .withId(id);

        if (this.tenant) {
          deleter = deleter.withTenant(this.tenant);
        }

        await deleter.do();
      }
    } else if (filter) {
      let batchDeleter = this.client.batch
        .objectsBatchDeleter()
        .withClassName(this.indexName)
